import{_ as n,C as o,o as e,c as r,a2 as t,b as h,w as a,a as l,E as p,a3 as d}from"./chunks/framework.Ci_RTJJ5.js";const b=JSON.parse('{"title":"11 — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/12-mcp/overview.md","filePath":"chapters/12-mcp/overview.md"}'),c={name:"chapters/12-mcp/overview.md"};function k(u,s,g,E,m,y){const i=o("Mermaid");return e(),r("div",null,[s[1]||(s[1]=t(`<h1 id="_11-—-overview" tabindex="-1">11 — Overview <a class="header-anchor" href="#_11-—-overview" aria-label="Permalink to &quot;11 — Overview&quot;">​</a></h1><p><em>How MCP works over stdio. Read this before you write code.</em></p><hr><h2 id="the-whole-protocol-is-a-pipe-and-lines" tabindex="-1">The whole protocol is a pipe and lines <a class="header-anchor" href="#the-whole-protocol-is-a-pipe-and-lines" aria-label="Permalink to &quot;The whole protocol is a pipe and lines&quot;">​</a></h2><p>MCP is often described in terms of capabilities, resources, prompts, and sampling. The transport underneath is smaller than any of that:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  your process                            server process</span></span>
<span class="line"><span>  ────────────                            ──────────────</span></span>
<span class="line"><span>  spawn ───────────────────────────────▶  starts</span></span>
<span class="line"><span>  write {&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;id&quot;:1,&quot;method&quot;:&quot;initialize&quot;,...}\\n</span></span>
<span class="line"><span>                                          read a line, answer</span></span>
<span class="line"><span>  ◀────────────────────────────────────── {&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;id&quot;:1,&quot;result&quot;:{...}}\\n</span></span></code></pre></div><p>One JSON object per line. Requests carry an <code>id</code>; the response carries the same <code>id</code>. Notifications have no <code>id</code> and get no response. That is the framing.</p>`,7)),(e(),h(d,null,{default:a(()=>[p(i,{id:"mermaid-17",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Agent%0A%20%20%20%20participant%20Server%0A%20%20%20%20Agent-%3E%3EServer%3A%20initialize%20%7BprotocolVersion%2C%20clientInfo%7D%0A%20%20%20%20Server--%3E%3EAgent%3A%20%7BserverInfo%2C%20capabilities%7D%0A%20%20%20%20Agent-%3E%3EServer%3A%20notifications%2Finitialized%0A%20%20%20%20Agent-%3E%3EServer%3A%20tools%2Flist%0A%20%20%20%20Server--%3E%3EAgent%3A%20%7Btools%3A%5B%7Bname%2C%20description%2C%20inputSchema%7D%5D%7D%0A%20%20%20%20Agent-%3E%3EServer%3A%20tools%2Fcall%20%7Bname%2C%20arguments%7D%0A%20%20%20%20Server--%3E%3EAgent%3A%20%7Bcontent%3A%5B%7Btype%3A%22text%22%2C%20text%3A%22...%22%7D%5D%7D%0A"})]),fallback:a(()=>[...s[0]||(s[0]=[l(" Loading... ",-1)])]),_:1})),s[2]||(s[2]=t(`<p>Three details that cost time if you get them wrong:</p><ul><li><strong><code>initialize</code> is a request.</strong> It has an id and you wait for the answer.</li><li><strong><code>notifications/initialized</code> is a notification.</strong> No id, no response. Strict servers wait for it before answering anything else.</li><li><strong>Responses and notifications share the stream.</strong> A reader that assumes the next line is its answer will hang the first time the server sends a log notification.</li></ul><h2 id="why-the-server-s-name-is-in-the-tool-name" tabindex="-1">Why the server&#39;s name is in the tool name <a class="header-anchor" href="#why-the-server-s-name-is-in-the-tool-name" aria-label="Permalink to &quot;Why the server&#39;s name is in the tool name&quot;">​</a></h2><p>A server may expose a tool called <code>read</code>. So does the agent. If the names collide, the server&#39;s version silently replaces the built-in one, and a file the model believes it read from disk came from somewhere else.</p><p>Namespacing removes the ambiguity:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  built-in:   read          write          bash          task</span></span>
<span class="line"><span>  server:     demo.read     demo.echo</span></span></code></pre></div><p>The prefix is the server&#39;s own reported name, sanitised to lowercase and dashes. If the server reports nothing usable, <code>mcp</code> is the fallback. The important property is that the name is derived, not hardcoded, so two servers with a <code>read</code> do not fight.</p><h2 id="adapters-not-special-cases" tabindex="-1">Adapters, not special cases <a class="header-anchor" href="#adapters-not-special-cases" aria-label="Permalink to &quot;Adapters, not special cases&quot;">​</a></h2><p>The registry already dispatches by name, the loop already appends results, and the prompt already lists schemas. A server tool becomes ordinary the moment it satisfies the <code>Tool</code> interface:</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcpTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                  { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t.server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t.info.Name }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcpTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Parameters</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">any</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t.info.InputSchema }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcpTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t.client.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CallTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, t.info.Name, input)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Nothing in the loop changed to support MCP. That is the last time the course makes this point, and it is the reason the previous ten chapters built seams.</p><h2 id="content-is-a-list-not-a-string" tabindex="-1">Content is a list, not a string <a class="header-anchor" href="#content-is-a-list-not-a-string" aria-label="Permalink to &quot;Content is a list, not a string&quot;">​</a></h2><p>A <code>tools/call</code> result carries content blocks:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;echo: hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;(second block)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}</span></span></code></pre></div><p>Two rules:</p><ul><li><strong>Join the text blocks.</strong> Taking only the first loses most answers.</li><li><strong>Ignore types you cannot use.</strong> An image block is base64 that would spend the context budget on something the model cannot see here.</li></ul><p>A server can also set <code>isError: true</code> on a successful response. That is a tool that ran and failed, and it becomes an error result like any other.</p><h2 id="failure-has-two-shapes" tabindex="-1">Failure has two shapes <a class="header-anchor" href="#failure-has-two-shapes" aria-label="Permalink to &quot;Failure has two shapes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Response</th><th>Agent behaviour</th></tr></thead><tbody><tr><td>the server will not start</td><td>no process</td><td>warn on stderr, continue without its tools</td></tr><tr><td>the handshake fails</td><td>no valid <code>initialize</code> answer</td><td>warn, continue</td></tr><tr><td>the server refuses a call</td><td>JSON-RPC <code>error</code> object</td><td>error result, session continues</td></tr><tr><td>the server dies mid-run</td><td>EOF on the pipe</td><td>error result for the call in flight</td></tr></tbody></table><p>The first two are startup problems, and the agent is still useful without the extension. The last two are per-call problems, and the model can read them.</p><p>An optional extension that stops the whole program is a bad trade. A person asked a question; they did not ask for a working plugin.</p><h2 id="synchronous-one-call-at-a-time" tabindex="-1">Synchronous, one call at a time <a class="header-anchor" href="#synchronous-one-call-at-a-time" aria-label="Permalink to &quot;Synchronous, one call at a time&quot;">​</a></h2><p>This client serialises requests: send, wait, return. That is enough because the loop runs tools in order.</p><p>The version that scales sends several calls at once and matches responses by id. That needs a reader goroutine, a map of pending ids, and a rule for what happens when a response arrives for a call whose context was cancelled. It is a real design, and it is a chapter on its own.</p><h2 id="what-this-chapter-does-not-do" tabindex="-1">What this chapter does not do <a class="header-anchor" href="#what-this-chapter-does-not-do" aria-label="Permalink to &quot;What this chapter does not do&quot;">​</a></h2><ul><li><strong>No HTTP or SSE transport.</strong> stdio only.</li><li><strong>No resources, prompts, or sampling.</strong> Tools are the part a coding agent uses.</li><li><strong>No reconnection.</strong> If the server dies, its tools return errors for the rest of the run.</li><li><strong>No MCP tools for subagents.</strong> The child registry is built from built-in tools, which also keeps the child&#39;s schema list small.</li></ul><h2 id="where-the-real-implementations-go-further" tabindex="-1">Where the real implementations go further <a class="header-anchor" href="#where-the-real-implementations-go-further" aria-label="Permalink to &quot;Where the real implementations go further&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Implementation</th></tr></thead><tbody><tr><td>Official Go SDK</td><td>crush <code>internal/mcp</code></td></tr><tr><td>Hand-rolled JSON-RPC</td><td>pi and PiG MCP clients</td></tr><tr><td>Server lifecycle and restart</td><td>crush <code>internal/mcp</code></td></tr><tr><td>Lazy tool schemas for many servers</td><td>toolflow, stage-gated mounting</td></tr></tbody></table><p>The survey behind this course found both approaches in production: crush delegates to the official SDK, pi hand-rolls the framing. This chapter hand-rolls it because the framing is the lesson, and because a dependency would hide the forty lines that matter.</p><h2 id="self-check" tabindex="-1">Self-check <a class="header-anchor" href="#self-check" aria-label="Permalink to &quot;Self-check&quot;">​</a></h2><ol><li>What is the framing, and how do you tell a request from a notification? <em>(The whole protocol is a pipe and lines)</em></li><li>Which two requests must happen before <code>tools/call</code>, in what order? <em>(The whole protocol is a pipe and lines)</em></li><li>Why is the server&#39;s name part of the tool name? <em>(Why the server&#39;s name is in the tool name)</em></li><li>What does the loop know about MCP? <em>(Adapters, not special cases)</em></li><li>Which two failures are startup problems, and which two are per-call problems? <em>(Failure has two shapes)</em></li></ol>`,31))])}const v=n(c,[["render",k]]);export{b as __pageData,v as default};
